import {demoProfile,forecast,purchaseScenario} from './demo-engine.js';
const profile=demoProfile(),base=forecast(profile,profile.demoAsOf);
const money=n=>(n<0?'−':'')+'$'+Math.abs(n).toLocaleString('en-US',{maximumFractionDigits:2});
const month=m=>new Date(m+'-15T12:00:00').toLocaleDateString('en-US',{month:'long'});
const set=(id,value)=>document.getElementById(id).textContent=value;
const buffer=base.breakdown.buffer,svg=document.getElementById('purchase-chart'),input=document.getElementById('purchase-amount');
let selected='2026-10-15';
set('cash',money(base.breakdown.cash));set('spend',money(base.availableToSpend));
const labels={cash:'Cash on September 7, 2026',obligations:'Bills due within 90 days',buffer:'Minimum cushion',seasonalReserve:'Held for months when costs exceed income',snapshot:'Left after these amounts',forecastHeadroom:'Room above the cushion at the lowest month'};
document.getElementById('math').innerHTML=Object.entries(labels).map(([key,label])=>'<div><dt>'+label+'</dt><dd>'+money(base.breakdown[key])+'</dd></div>').join('');
set('spending-bridge',`The snapshot leaves ${money(base.breakdown.snapshot)}, but the forecast has only ${money(base.breakdown.forecastHeadroom)} above your cushion at its lowest month. Estimated spending room uses the smaller amount, never below zero: ${money(base.availableToSpend)}.`);
function update(){
 const raw=input.value,amount=Number(raw),valid=raw.trim()!==''&&Number.isFinite(amount)&&amount>=0&&amount<=1e9&&/^\d+(\.\d{0,2})?$/.test(raw);
 input.setAttribute('aria-invalid',String(!valid));document.getElementById('result-month-wrap').hidden=!valid;document.getElementById('purchase-error').hidden=valid;
 document.querySelector('.chart').hidden=!valid;document.querySelector('.demo-details').hidden=!valid;
 document.querySelectorAll('[data-date]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.date===selected)));
 if(!valid){set('march-value','Enter an amount');set('low-month','');set('scenario-status','No forecast shown until the amount is valid.');set('october-low','—');set('may-low','—');return;}
 const result=purchaseScenario(profile,profile.demoAsOf,amount,selected),oct=purchaseScenario(profile,profile.demoAsOf,amount,'2026-10-15'),may=purchaseScenario(profile,profile.demoAsOf,amount,'2027-05-15');
 set('march-value',money(result.after.projectedLow.amount));set('low-month',month(result.after.projectedLow.month));
 set('scenario-status',result.shortfall>0?`Projected low · Below your ${money(buffer)} cushion`:`Projected low · At or above your ${money(buffer)} cushion at each month end`);
 set('baseline-low',`Without: ${money(base.projectedLow.amount)} in ${month(base.projectedLow.month)}`);
 set('purchase-low',`With: ${money(result.after.projectedLow.amount)} in ${month(result.after.projectedLow.month)}`);
 set('october-low',`${money(oct.after.projectedLow.amount)} · ${month(oct.after.projectedLow.month)}`);set('may-low',`${money(may.after.projectedLow.amount)} · ${month(may.after.projectedLow.month)}`);
 set('explanation',`The ${money(amount)} purchase reduces cash from ${month(selected.slice(0,7))} onward. These are month-end estimates, not a guarantee.`);
 set('base-copy',`Without purchase: ${money(base.projectedLow.amount)} low in ${month(base.projectedLow.month)}.`);
 set('oct-copy',`October purchase: ${money(oct.after.projectedLow.amount)} low in ${month(oct.after.projectedLow.month)}.`);
 set('may-copy',`May purchase: ${money(may.after.projectedLow.amount)} low in ${month(may.after.projectedLow.month)}.`);
 const width=Math.max(250,svg.clientWidth),height=230,left=58,right=20,top=28,bottom=32;
 const min=Math.min(0,...result.after.points.map(p=>p.projectedCash)),max=Math.max(buffer,...base.points.map(p=>p.projectedCash));
 const step=Math.max(20000,Math.ceil((max-min)/4/20000)*20000),lo=Math.floor(min/step)*step,hi=Math.ceil(max/step)*step;
 const x=i=>left+i*(width-left-right)/11,y=n=>top+(hi-n)/(hi-lo)*(height-top-bottom),points=r=>r.points.map((p,i)=>x(i)+','+y(p.projectedCash)).join(' ');
 svg.setAttribute('viewBox',`0 0 ${width} ${height}`);
 const ticks=Array.from({length:Math.round((hi-lo)/step)+1},(_,i)=>lo+i*step);
 const lowMarker=(r,color,offset)=>{const i=r.points.findIndex(p=>p.month===r.projectedLow.month),cx=x(i),cy=y(r.projectedLow.amount);return `<circle cx="${cx}" cy="${cy}" r="5" fill="${color}"/>`+(width>600?`<text x="${Math.min(Math.max(cx,150),width-150)}" y="${Math.max(18,Math.min(height-42,cy+offset))}" text-anchor="middle" style="fill:${color};paint-order:stroke;stroke:#101214;stroke-width:5px">${money(r.projectedLow.amount)} ${offset<0?'without':'with'}</text>`:'');};
 svg.innerHTML='<title>Projected month-end cash, September 2026 to August 2027</title>'+ticks.map(n=>`<text x="${left-8}" y="${y(n)+5}" text-anchor="end">${n<0?'−':''}$${Math.abs(n)>=1e6?(Math.abs(n)/1e6).toFixed(1)+'m':Math.abs(n)/1000+'k'}</text>`).join('')+`<line x1="${left}" x2="${width-right}" y1="${y(buffer)}" y2="${y(buffer)}" stroke="#adb5b8" stroke-dasharray="2 5"/><polyline fill="none" stroke="#f2f3f1" stroke-width="3" points="${points(base)}"/><polyline class="scenario-line" fill="none" stroke="#91bec8" stroke-width="3" stroke-dasharray="8 5" points="${points(result.after)}"/>`+lowMarker(base,'#f2f3f1',-18)+lowMarker(result.after,'#c8e1e5',24)+[0,3,6,11].map(i=>`<text x="${x(i)}" y="${height-4}" text-anchor="middle">${base.points[i].label.split(' ')[0]}</text>`).join('');
 svg.setAttribute('aria-label',`Projected month-end cash. Without purchase: ${money(base.projectedLow.amount)} low in ${month(base.projectedLow.month)}. With purchase: ${money(result.after.projectedLow.amount)} low in ${month(result.after.projectedLow.month)}. Cushion ${money(buffer)}.`);
 document.getElementById('monthly-values').innerHTML=base.points.map((p,i)=>`<tr><th scope="row">${p.label}</th><td>${money(p.projectedCash)}</td><td>${money(result.after.points[i].projectedCash)}</td></tr>`).join('');
}
input.disabled=false;input.addEventListener('input',update);
document.querySelectorAll('[data-date]').forEach(button=>{button.disabled=false;button.addEventListener('click',()=>{selected=button.dataset.date;update();});});
window.addEventListener('resize',update);update();
